(async()=>{
  const E=window.__echoes; const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
  const trace=[]; let guard=0, lastRoom=0, dwell=0;
  E.cmd("startRun");
  while(guard++<900){
    const v=E.cmd("runState");
    if(v.phase==="reward"){ trace.push("STOP "+v.phase+" room"+v.room); break; }
    if(v.phase==="victory"||v.phase==="defeat"){ trace.push("END "+v.phase); break; }
    if(v.phase==="combat"){ if(v.room!==lastRoom){lastRoom=v.room;dwell=0;trace.push("ROOM "+v.room+" "+v.mode);} dwell++; E.cmd("killAllEnemies"); if(v.mode==="defend"&&dwell>18) E.cmd("clearRoom"); }
    else if(v.phase==="reward"){ trace.push("REWARD "+v.reward.type+":"+v.reward.id); E.cmd("draftTake"); E.cmd("closeSocket"); }
    else if(v.phase==="path"){ E.cmd("pathChoose",0); }
    else if(v.phase==="shop"){ E.cmd("shopAdvance"); }
    await sleep(70);
  }
  return trace;
})()
